		local typeColors = {
			Success = C.Ok,
			Warning = C.Warn,
			Error = C.Err,
			Info = C.Info,
		}

		local history = W._notifHistory
		for i = #history, 1, -1 do
			local entry = history[i]
			local row = Instance.new("Frame")
			noHit(row)
			row.BackgroundColor3 = C.Surface
			row.BackgroundTransparency = 0.4
