		chBot.Size = UDim2.new(0, th, 0, sz)
		chBot.Position = UDim2.new(0.5, 0, 0.5, gp)
		chLeft.Size = UDim2.new(0, sz, 0, th)
		chLeft.Position = UDim2.new(0.5, -gp, 0.5, 0)
		chRight.Size = UDim2.new(0, sz, 0, th)
